```

**修改后**：
```typescript
private async buildTools(options) {
  // 从 MotorToolRunner 获取默认工具
  const motorTools = await this.toolAdapterService.getAllTools();

  if (options.toolPreset === 'default') {
    return motorTools;
  }
  // ... coding 模式
}
```

